// Khởi tạo các biến nếu chưa có
let metalCount = flow.get('metalCount') || 0;
let totalCount = flow.get('totalCount') || 0;
let lastState = context.get('lastState') || false;

// 1. TUYỆT ĐỐI BỎ QUA CÁC LỆNH ĐIỀU KHIỂN BĂNG TẢI, NGẮT KẾT NỐI, CLEAR LOG
if (msg.topic === "conveyor_cmd" || msg.topic === "simulate_disconnect" || msg.topic === "clear_log") {
    return null;
}

// 2. Xử lý nút Reset
if (msg.topic === "reset" || msg.payload === "reset") {
    metalCount = 0;
    totalCount = 0;
    flow.set('metalCount', 0);
    flow.set('totalCount', 0);
    context.set('lastState', false);
    return [
        { payload: 0, topic: "metal" },     // Out 1: SP Kim loại
        { payload: 0, topic: "total" },     // Out 2: Tổng sản phẩm
        null                                // Out 3: Kích hoạt Solenoid
    ];
}

// 3. Xử lý nút Thả SP Phi kim
if (msg.topic === "non_metal" || msg.payload === "non_metal") {
    totalCount += 1;
    flow.set('totalCount', totalCount);
    return [
        null,
        { payload: totalCount, topic: "total" },
        null
    ];
}

// 4. Xử lý Thả Kim loại giả lập hoặc Cảm biến IN1 thật
let isMetal = false;
let isSimulated = (msg.topic === "simulate_metal");

if (isSimulated) {
    isMetal = true;
} else if (msg.topic === "" || msg.topic === "sensor" || !msg.topic) {
    // Chỉ đọc từ cảm biến thực tế khi topic rỗng hoặc là sensor
    if (Array.isArray(msg.payload)) {
        isMetal = Boolean(msg.payload[0]);
    } else if (typeof msg.payload === "boolean") {
        isMetal = msg.payload;
    }
}

// Kích hoạt khi có sườn lên (hoặc khi bấm nút Giả lập Thả kim loại)
if (isMetal && (!lastState || isSimulated)) {
    if (!isSimulated) context.set('lastState', true);
    metalCount += 1;
    totalCount += 1;
    flow.set('metalCount', metalCount);
    flow.set('totalCount', totalCount);

    return [
        { payload: metalCount, topic: "metal" },   // Out 1: SP Kim loại
        { payload: totalCount, topic: "total" },   // Out 2: Tổng sản phẩm
        { payload: [true], topic: "trigger" }      // Out 3: Kích hoạt Solenoid
    ];
} else if (!isMetal && !isSimulated) {
    context.set('lastState', false);
}

return null;

// Quản lý Trạng thái & Nhật ký SCADA
let state = flow.get('scada_state') || 'STOPPED';
let statusText = flow.get('scada_statusText') || 'Hệ thống đang dừng';
let conveyorRunning = flow.get('conveyorRunning') || false;
let metalCount = flow.get('metalCount') || 0;
let totalCount = flow.get('totalCount') || 0;
let eventLog = flow.get('eventLog') || [];

let now = new Date();
let timeStr = now.toTimeString().split(' ')[0];
let soundTrigger = null;

function addEvent(tag, tagType, text) {
    eventLog.unshift({
        time: timeStr,
        tag: tag,
        tagType: tagType,
        text: text,
        metal: flow.get('metalCount') || metalCount,
        total: flow.get('totalCount') || totalCount
    });
    if (eventLog.length > 50) eventLog.pop();
    flow.set('eventLog', eventLog);
}

// 1. Chuyển đổi Chế độ Thực tế / Mô phỏng
if (msg.topic === 'mode_change') {
    if (msg.payload === 'real') {
        soundTrigger = 'beep';
        addEvent('CHẾ ĐỘ', 'primary', 'Chuyển sang chế độ VẬN HÀNH THỰC TẾ');
    } else {
        soundTrigger = 'beep';
        addEvent('CHẾ ĐỘ', 'warning', 'Chuyển sang chế độ MÔ PHỎNG (DEMO)');
    }
}

// 2. Điều khiển Băng chuyền (BẬT / TẮT)
else if (msg.topic === 'conveyor_cmd') {
    let run = false;
    if (Array.isArray(msg.payload)) run = Boolean(msg.payload[0]);
    else run = Boolean(msg.payload);

    if (run) {
        conveyorRunning = true;
        state = 'RUNNING';
        statusText = 'Băng chuyền đang hoạt động';
        soundTrigger = 'beep';
        addEvent('START', 'success', 'Khởi động băng tải vận hành');
    } else {
        conveyorRunning = false;
        state = 'STOPPED';
        statusText = 'Băng chuyền đã dừng';
        soundTrigger = 'beep';
        addEvent('STOP', 'danger', 'Dừng băng tải an toàn');
    }
}

// 3. Sự kiện Thả Kim loại giả lập
else if (msg.topic === 'simulate_metal') {
    state = 'SORTING';
    statusText = 'Đang phân loại SP kim loại mới';
    soundTrigger = 'chime';
    addEvent('THẢ KIM LOẠI', 'warning', 'Thả SP kim loại vào băng chuyền');
}

// 4. Solenoid kích hoạt gạt
else if (msg.topic === 'solenoid_on' || (msg.payload && msg.payload[0] === true && msg.adr === 1)) {
    state = 'SORTING';
    statusText = 'Xi-lanh Solenoid đang đẩy gạt kim loại';
    soundTrigger = 'chime';
    addEvent('GẠT SP', 'warning', 'Solenoid kích hoạt gạt sản phẩm kim loại');
}

// 5. Solenoid thu hồi
else if (msg.topic === 'solenoid_off' || msg.payload === false) {
    state = conveyorRunning ? 'RUNNING' : 'STOPPED';
    statusText = conveyorRunning ? 'Băng chuyền đang hoạt động' : 'Băng chuyền đã dừng';
    addEvent('THU HỒI', 'info', 'Thu hồi Solenoid về vị trí chờ');
}

// 6. Cảm biến phát hiện kim loại
else if (msg.topic === 'metal') {
    metalCount = msg.payload;
    if (metalCount > 0) {
        state = 'SORTING';
        statusText = 'Cảm biến IN1 phát hiện SP kim loại #' + metalCount;
        soundTrigger = 'chime';
        addEvent('KIM LOẠI', 'warning', 'Cảm biến IN1 phát hiện kim loại #' + metalCount);
    }
}

// 7. Thả Phi kim
else if (msg.topic === 'non_metal') {
    totalCount = flow.get('totalCount') || 0;
    soundTrigger = 'beep';
    addEvent('PHI KIM', 'primary', 'Ghi nhận SP phi kim trôi qua băng tải');
}

// 8. Reset
else if (msg.topic === 'reset') {
    metalCount = 0;
    totalCount = 0;
    soundTrigger = 'beep';
    addEvent('RESET', 'danger', 'Đã đặt lại toàn bộ bộ đếm về 0');
}

// 9. Xóa log
else if (msg.topic === 'clear_log') {
    eventLog = [];
    flow.set('eventLog', eventLog);
    addEvent('DỌN DẸP', 'info', 'Đã xóa toàn bộ nhật ký vận hành');
}

// Lưu trạng thái
flow.set('scada_state', state);
flow.set('scada_statusText', statusText);
flow.set('conveyorRunning', conveyorRunning);

msg.payload = {
    state: state,
    statusText: statusText,
    conveyorRunning: conveyorRunning,
    metalCount: flow.get('metalCount') || 0,
    totalCount: flow.get('totalCount') || 0,
    events: eventLog,
    soundTrigger: soundTrigger,
    time: timeStr
};

return msg;

// Gate kiểm tra tín hiệu Heartbeat
let isBlocked = flow.get('heartbeat_blocked') || false;

if (msg.topic === 'simulate_disconnect') {
    isBlocked = Boolean(msg.payload);
    flow.set('heartbeat_blocked', isBlocked);
    if (isBlocked) {
        // Đã ngắt: không gửi gì để node trigger hết 5s sẽ báo Timeout!
        return null;
    } else {
        // Khôi phục: gửi ngay tín hiệu ping để trigger phục hồi Connected
        return { payload: true, topic: 'heartbeat_ping' };
    }
}

// Nếu nhận heartbeat định kỳ từ inject hoặc modbus
if (!isBlocked) {
    return { payload: true, topic: 'heartbeat_ping' };
}

return null;
